/// Only exact gateway-owned rejection codes may be retained from an HTTP body.
#[derive(Debug, PartialEq, Eq)]
struct ThreechedConnectionFailure {
    kind: &'static str,
    http_status: Option<u16>,
    gateway_reason: &'static str,
}

fn log_threeched_connection_failure(
    stage: &'static str,
    error: &tokio_tungstenite::tungstenite::Error,
) {
    let failure = threeched_connection_failure(error);
    tracing::warn!(
        stage,
        kind = failure.kind,
        http_status = ?failure.http_status,
        gateway_reason = failure.gateway_reason,
        "threeched generation connection failed"
    );
}

